import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

Blockly.Blocks['array_create'] = {
  init: function() {
    this.appendDummyInput()
        .appendField("[")
        .appendField(new Blockly.FieldTextInput("1, 2, 3"), "VALUES") // Nhập từ bàn phím
        .appendField("]");
    this.setOutput(true, "Array");
    this.setColour(230); // Màu tím
    this.setTooltip("Enter values separated by commas to create an array.");
  }
};

// Python Generator
pythonGenerator.forBlock['array_create'] = function(block) {
  const values = block.getFieldValue('VALUES').split(',').map(v => v.trim()); // Tách từng phần tử
  return [`[${values.join(', ')}]`, pythonGenerator.ORDER_ATOMIC];
};

Blockly.Blocks['get_value_by_index'] = {
  init: function() {
    this.appendDummyInput()
        .appendField(new Blockly.FieldVariable("ARRAY"),"ARRAY");
        this.appendDummyInput()
            .appendField("[")
            .appendField(new Blockly.FieldTextInput([["0"]]), "INDEX");
    this.appendDummyInput()
        .appendField("]")
    this.setOutput(true, "Number");
    this.setInputsInline(true);
    this.setColour(230); // Màu tím
    this.setTooltip("Enter the index of the array to get the value.");
  }
};

pythonGenerator.forBlock['get_value_by_index'] = function(block) {
  const index = block.getFieldValue('INDEX');
  const array = block.getFieldValue('ARRAY');
  return [`${array}[${index}]`, pythonGenerator.ORDER_ATOMIC];
};

Blockly.Blocks['set_value_by_index'] = {
  init: function() {
    this.appendDummyInput()
        .appendField(new Blockly.FieldVariable("ARRAY"),"ARRAY")
    this.appendDummyInput()
        .appendField("[")
        .appendField(new Blockly.FieldTextInput([["0"]]), "INDEX");
    this.appendValueInput("VALUE")
        .appendField("]=")
    this.setInputsInline(true);
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(230); // Màu tím
    this.setTooltip("Enter the index of the array to set the value.");
  }
};  

pythonGenerator.forBlock['set_value_by_index'] = function(block) {
  const index = block.getFieldValue('INDEX');
  const array = block.getFieldValue('ARRAY');
  const value = pythonGenerator.valueToCode(block, 'VALUE', pythonGenerator.ORDER_ATOMIC);
  return [`${array}[${index}] = ${value}`, pythonGenerator.ORDER_ATOMIC];
};

Blockly.Blocks['array_length'] = {
  init: function() {
    this.appendDummyInput()
        .appendField("length of")
    this.appendDummyInput()
        .appendField(new Blockly.FieldVariable("ARRAY"),"ARRAY")
    this.setOutput(true, "Number");
    this.setColour(230); // Màu tím
    this.setTooltip("Get the length of the array.");
  }
};

